public class Compiler_toSource_TriageGen0Test {

  private Compiler compiler;
  private CompilerOptions options;
  private CodeBuilder cb;

  @Mock
  private Node mockRoot;

  @Mock
  private JSDocInfo mockJSDocInfo;

  @Before
  public void setUp() {
    MockitoAnnotations.openMocks(this);
    compiler = spy(new Compiler());
    options = new CompilerOptions();
    compiler.initOptions(options);
    cb = new CodeBuilder();
  }

  @Test
  public void testToSource_BasicNoOptions() {
    // Mocking toSource(root, sourceMap) inside the callable via spy if possible, 
    // but since it's a private/internal call to another method in the same class, 
    // we rely on the fact that toSource(Node, SourceMap) is called.
    // We will simulate a simple node.
    Node root = new Node.Impure(Token.SCRIPT);
    root.addChild(new Node.Impure(Token.VAR));

    compiler.toSource(cb, 1, root);

    String result = cb.toString();
    // The code should contain the semicolon logic
    assertTrue(result.contains(";"));
  }

  @Test
  public void testToSource_WithPrinterDelimiter() {
    options.printInputDelimiter = true;
    options.inputDelimiter = "/* %name%:%num% */";

    Node root = new Node.Impure(Token.SCRIPT);
    root.setProperty(Node.SOURCENAME_PROP, "test.js");

    // Pre-fill CB to test newline logic
    cb.append("existing");

    compiler.toSource(cb, 5, root);

    String result = cb.toString();
    // Check if newline was added before delimiter
    assertTrue(result.contains("existing\n/* test.js:5 */"));
  }

  @Test
  public void testToSource_WithLicense() {
    when(mockRoot.getJSDocInfo()).thenReturn(mockJSDocInfo);
    when(mockJSDocInfo.getLicense()).thenReturn("MIT License");

    Node root = new Node.Impure(Token.SCRIPT);
    root.setJSDocInfo(mockJSDocInfo);

    compiler.toSource(cb, 1, root);

    String result = cb.toString();
    assertTrue(result.contains("/*\nMIT License*/"));
  }

  @Test
  public void testToSource_SourceMapOffset() {
    options.sourceMapOutputPath = "out.map";
    Node root = new Node.Impure(Token.SCRIPT);

    // We trigger the sourceMap.setStartingPosition call
    compiler.toSource(cb, 1, root);

    // Since we can't easily verify the internal state of the private sourceMap 
    // without reflection, we ensure no exception is thrown.
  }

  @Test
  public void testToSource_SemicolonHeuristics() {
    // Case 1: No semicolon at end
    Node root1 = new Node.Impure(Token.SCRIPT);
    root1.addChild(new Node.Impure(Token.VAR)); // Represents "var"
    // We need to mock the internal toSource(root, sourceMap) 
    // This is tricky because it's a real call. Let's use a node that produces content.

    // We will use a real compiler flow for a tiny snippet to ensure valid 'code' string
    Compiler realCompiler = new Compiler();
    realCompiler.compile(Collections.emptyList(), Collections.singletonList(
        JSSourceFile.parse("test.js", "var x = 1")), new CompilerOptions());

    // Use a node from a real compilation to ensure code is not empty
    Node root = realCompiler.getRoot();

    // Test: Code ends in char (not ;)
    // We can't easily force the return of the internal toSource without mocking the whole compiler.
    // However, we can test the logic by checking if semicolon is appended.

    realCompiler.toSource(cb, 1, root);
    String result = cb.toString();
    assertTrue(result.endsWith(";"));
  }

  @Test
  public void testToSource_SemicolonAlreadyExists() {
    // If code is "var x = 1;", the semicolon shouldn't be doubled.
    // This is hard to test purely via unit test without deep mocking of the 'toSource(Node, SourceMap)' method.
    // But we can simulate it if the code returned ends in ';'

