  @Test(expected = RuntimeException.class)
  public void testToSource_ThrowsOnInvalidRootType() {
    options.printInputDelimiter = true;
    options.inputDelimiter = "delim";
    Node wrongRoot = new Node.Impure(Token.EXPRESSION); // Not SCRIPT

    compiler.toSource(cb, 1, wrongRoot);
  }

  @Test(expected = RuntimeException.class)
  public void testToSource_ThrowsOnMissingSourceName() {
    options.printInputDelimiter = true;
    options.inputDelimiter = "delim";
    Node root = new Node.Impure(Token.SCRIPT);
    // SOURCENAME_PROP is null

    compiler.toSource(cb, 1, root);
  }
